import{_ as i,C as d,c as l,o as s,aa as e,G as r}from"./chunks/framework.Cn7WEiMX.js";const g=JSON.parse('{"title":"配置文件","description":"","frontmatter":{"breadcrumbs":[{"title":"Continue Project","link":"/wiki"},{"title":"WorldEdit","link":"/wiki/WorldEdit"},{"title":"配置文件","link":"/wiki/WorldEdit/configuration"}]},"headers":[],"relativePath":"wiki/WorldEdit/configuration.md","filePath":"wiki/WorldEdit/configuration.md"}'),n={name:"wiki/WorldEdit/configuration.md"};function c(f,t,u,p,h,m){const o=d("NolebaseGitContributors"),a=d("NolebaseGitChangelog");return s(),l("div",null,[t[0]||(t[0]=e('<h1 id="配置文件" tabindex="-1">配置文件 <a class="header-anchor" href="#配置文件" aria-label="Permalink to &quot;配置文件&quot;">​</a></h1><p>尽管 WorldEdit 在大部分情况下只需要使用命令，但是用户还是可以通过设置配置文件来决定 WorldEdit 的工具或命令的限制或变动。</p><h2 id="配置文件-1" tabindex="-1">配置文件 <a class="header-anchor" href="#配置文件-1" aria-label="Permalink to &quot;配置文件&quot;">​</a></h2><p>只要你运行了安装 WorldEdit 的服务器，你就可以在相应的位置找到本插件的配置文件。</p><h3 id="bukkit-服务器" tabindex="-1">Bukkit 服务器 <a class="header-anchor" href="#bukkit-服务器" aria-label="Permalink to &quot;Bukkit 服务器&quot;">​</a></h3><p>Bukkit 版本的 WorldEdit 的配置文件可以在 <code>plguins/WorldEdit/config.yml</code>，一般位于服务器核心的同级目录下<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup>。</p><p>需要注意的是，Bukkit 所使用的 YAML 格式配置文件容错率很低。在文件中使用的缩进必须使用四个空格（TAB 缩进符会破坏文件结构！），且要一直遵守 YAML 的格式。如果你很少或从未编辑过 YAML 类型的文件的话，你可以将你的配置文件放进一些在线格式检测器中（例如<a href="https://yaml-online-parser.appspot.com/" target="_blank" rel="noreferrer">这个网站</a><sup class="footnote-ref"><a href="#fn2" id="fnref2">[2]</a></sup>），并确保你所设置的配置文件中没有任何格式错误。</p><h3 id="forge-fabric-客户端-服务器" tabindex="-1">Forge/Fabric 客户端/服务器 <a class="header-anchor" href="#forge-fabric-客户端-服务器" aria-label="Permalink to &quot;Forge/Fabric 客户端/服务器&quot;">​</a></h3><p>NeoForge/Fabric 的配置文件选项可在 <code>config/worldedit/worldedit.properties</code> 文件中找到。在服务器中，这个文件则会对应存在于服务器的根目录下（也就是服务器核心 .jar 文件的同级目录附近）。在单人客户端中，这会存在于你的“.minecraft”文件夹下。</p><h3 id="sponge-服务器" tabindex="-1">Sponge 服务器 <a class="header-anchor" href="#sponge-服务器" aria-label="Permalink to &quot;Sponge 服务器&quot;">​</a></h3><p>在 Sponge 服务器中的配置文件（SpongeForge 或 SpongeVanilla）可以在 <code>config/worldedit/worldedit.conf</code> 文件中找到。</p><h2 id="配置选项" tabindex="-1">配置选项 <a class="header-anchor" href="#配置选项" aria-label="Permalink to &quot;配置选项&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">提示</p><p>鉴于现在服务端核心百花齐放的场景，其开发状态可能各有不同，所以不是该配置中的所有设置都能稳定运行在所有平台上。如果你发现了某项配置不能正常在游戏里工作，请提醒我们。</p></div><table tabindex="0"><thead><tr><th>设置项</th><th>默认值</th><th>描述</th></tr></thead><tbody><tr><td>defaultLocale</td><td>default</td><td>插件所使用的语言，默认情况下跟随系统语言。</td></tr><tr><td>profile</td><td>false</td><td>是否在操作后显示所有受到修改的方块及其时间点。</td></tr><tr><td>traceUnflushedSessions</td><td>false</td><td>在指定编辑未正确完全执行时显示调试信息。</td></tr><tr><td>disallowedBlocks</td><td>&lt;方块列表&gt;</td><td>放置图案参数中不能出现的方块（大多数受重力影响，会“掉落”的方块可能会造成服务器卡顿，甚至在量足够大的时候使服务器崩溃）。</td></tr><tr><td>defaultChangeLimit</td><td>-1</td><td>单次操作限制的影响方块数量默认上限。</td></tr><tr><td>maxChangeLimit</td><td>-1</td><td>单次操作限制的影响方块数量最大上限（游戏内可通过 <code>//limit</code> 命令修改）。</td></tr><tr><td>defaultMaxPolygonalPoints</td><td>-1</td><td>多边形所使用的默认顶点数量（<code>//sel poly</code>），-1 表示使用最大值。</td></tr><tr><td>maxPolygonalPoints</td><td>20</td><td>多边形所使用的最大顶点数量（<code>//sel poly</code>，在拥有权限 <code>worldedit.limit.unrestricted</code> 时使用）</td></tr><tr><td>defaultMaxPolyhedronPoints</td><td>-1</td><td>多面体所使用的默认顶点数量（<code>//sel convex</code>），-1 表示使用最大值。</td></tr><tr><td>maxPolyhedronPoints</td><td>20</td><td>多面体所使用的最大顶点数量（<code>//sel convex</code>，在拥有权限 <code>worldedit.limit.unrestricted</code> 时使用）</td></tr><tr><td>snapshotRepo</td><td></td><td>不为空时，即为名称对应的文件夹中的快照</td></tr><tr><td>snapshotsExperimental</td><td>false</td><td>如果设置为 true，则使用新的快照格式。可以试试，并在使用过程中报告可能的漏洞！</td></tr><tr><td>maxRadius</td><td>-1</td><td>需要半径参数的命令的最大半径。</td></tr><tr><td>maxSuperPickaxe</td><td>5</td><td>超级镐子工具最大的连锁破坏大小。</td></tr><tr><td>maxBrushRadius</td><td>6</td><td>笔刷工具的最大尺寸。</td></tr><tr><td>logCommands</td><td>false</td><td>是否记录使用命令的详细信息。</td></tr><tr><td>logFile</td><td></td><td>若上一个选项被设置为 true，则该项填入存储日志的位置。</td></tr><tr><td>logFormat</td><td><code>[%1$tY-%1$tm-%1$td %1$tH:%1$tM:%1$tS %4$s]: %5$s%6$s%n</code></td><td>记录命令的格式。</td></tr><tr><td>wandItem</td><td>minecraft:wooden_axe</td><td>圈定选区用的默认物品，可被已有游戏内设置覆盖。设置为 -1 表示不绑定任何物品。</td></tr><tr><td>superPickaxeDrop</td><td>true</td><td>超级镐子是否掉落其破坏的物品。</td></tr><tr><td>superPickaxeManyDrop</td><td>true</td><td>多个超级镐子触发时是否掉落其破坏的物品</td></tr><tr><td>useInventory</td><td>false</td><td>编辑时消耗玩家在背包中拥有对应的物品（该功能兼容性不佳，不推荐使用）。</td></tr><tr><td>useInventoryOverride</td><td>false</td><td>允许一个指定的权限节点覆盖上述设置。</td></tr><tr><td>useInventoryCreativeOverride</td><td>false</td><td>允许创造模式覆盖上述设置。</td></tr><tr><td>navigationUseGlass</td><td>true</td><td>如果玩家在使用 <code>/up</code> 或 <code>/ceil</code> 命令时目的地为空中，是否在他们脚下生成一块玻璃。</td></tr><tr><td>navigationWand</td><td>minecraft:compass</td><td>导航魔杖所使用的默认物品，绑定后手持该物品左键等价于输入命令 <code>/jumpto</code>，右键等价于 <code>/thru</code>，可被游戏内的设置覆盖。设置为 -1 表示不绑定任何物品。</td></tr><tr><td>navigationWandMaxDistance</td><td>50</td><td>导航魔杖使用的最大距离。</td></tr><tr><td>scriptTimeout</td><td>3000</td><td>快速脚本被强制结束前的最大等待时间。</td></tr><tr><td>calculationTimeout</td><td>100</td><td>计算命令被强制结束前的等待时间。</td></tr><tr><td>maxCalculationTimeout</td><td>300</td><td>计算命令被强制结束前的最大等待时间。</td></tr><tr><td>allowedDataCycleBlocks</td><td></td><td>若不为空，该设置列表中的方块可以用于数据同步工具。</td></tr><tr><td>saveDir</td><td>schematics</td><td>结构文件保存的路径（上级目录即为 worldedit 文件夹）</td></tr><tr><td>scriptsDir</td><td>craftscripts</td><td>快速脚本保存的路径。</td></tr><tr><td>allowSumlinks</td><td>false</td><td>是否允许上述内容使用连接位置（对跨服使用很有帮助）</td></tr><tr><td>butcherDefaultRadius</td><td>-1</td><td><code>/butcher</code> 命令的默认使用半径（-1 表示不限制）</td></tr><tr><td>butcherMaxRadius</td><td>-1</td><td><code>/butcher</code> 命令的最大使用半径（-1 表示不限制）</td></tr><tr><td>serverSideCUI</td><td>true</td><td>是否允许使用 <code>//drawsel</code> 命令显示选区。</td></tr><tr><td>defaultVerticalHeight</td><td>256</td><td>以高度为可选参数的命令所能设置对应参数的最大值。</td></tr><tr><td>extendedYLimit</td><td>false</td><td>若设置为 true，则允许选择没有高度限制的位置，但处理效率更低。仅建议在有模组能拓宽世界上限的情况时使用。</td></tr></tbody></table>',14)),r(o),r(a),t[1]||(t[1]=e('<hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p>译者注：即服务器核心的 .jar 文件旁边，字面意义上的旁边。 <a href="#fnref1" class="footnote-backref">↩︎</a></p></li><li id="fn2" class="footnote-item"><p>译者注：也可以使用 HelpChat 官方提供的 <a href="https://yaml.helpch.at/" target="_blank" rel="noreferrer">YAML 文件格式校验器</a>。 另外，也可使用一些编辑器例如 Visual Studio Code 所提供的检测功能，以 VSCode 为例，它会使用红色波浪线标出文本中不符合语法的地方。 <a href="#fnref2" class="footnote-backref">↩︎</a></p></li></ol></section>',2))])}const k=i(n,[["render",c]]);export{g as __pageData,k as default};
